<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=$pdo->prepare('UPDATE service_requests SET status=? WHERE id=?');$q->execute([$_POST['status']??'new',(int)$_POST['id']]);flash('Request status updated.');header('Location: requests.php');exit;}$rows=$pdo->query('SELECT * FROM service_requests ORDER BY created_at DESC')->fetchAll();$pageTitle='Service requests';include __DIR__.'/_header.php';?><div class="dash-top"><div><span class="eyebrow">Business technology</span><h1>Service requests</h1><p>Follow up enquiries from prospective clients.</p></div></div><section class="dash-panel"><h2>Incoming requests (<?=count($rows)?>)</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Client</th><th>Service</th><th>Message</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?> · <?=e($r['phone'])?></small></td><td><?=e($r['service'])?></td><td class="message-cell"><?=e($r['message'])?></td><td><?=e($r['created_at'])?></td><td><form method="post" class="status-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['new','in_progress','completed'] as $s):?><option value="<?=$s?>" <?=$s===$r['status']?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-small">Update</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No service requests received yet.</td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__.'/_footer.php';?>